5: /// Normalizes a path to be workspace-root-relative and UTF-8.
6: ///
7: /// Rejects absolute paths and non-UTF-8 paths, and normalizes `.` and `..` components
8: /// lexically (without accessing the filesystem).
9: pub fn workspace_relative(path: impl AsRef<Path>) -> Result<PathBuf, ModelError> {
10:     let p = path.as_ref();
11:     if p.is_absolute() {
12:         return Err(ModelError::AbsolutePath {
13:             path: p.to_path_buf(),
14:         });
15:     }
16: 
17:     if p.to_str().is_none() {
18:         return Err(ModelError::NonUtf8Path {
19:             path: p.to_path_buf(),
20:         });
21:     }
22: 
23:     let normalized_str = p.to_str().unwrap().replace('\\', "/");
24:     let normalized_path = Path::new(&normalized_str);
25: 
26:     let mut components = Vec::new();
27:     for component in normalized_path.components() {
28:         match component {
29:             Component::Prefix(_) | Component::RootDir => {
30:                 return Err(ModelError::AbsolutePath {
31:                     path: p.to_path_buf(),
32:                 });
33:             }
34:             Component::CurDir => {}
35:             Component::ParentDir => {
36:                 if let Some(Component::Normal(_)) = components.last() {
37:                     components.pop();
38:                 } else {
39:                     return Err(ModelError::PathTraversal {
40:                         path: p.to_path_buf(),
41:                     });
42:                 }
43:             }
44:             Component::Normal(_) => {
45:                 components.push(component);
46:             }
47:         }
48:     }
49: 
50:     let mut out_str = String::new();
51:     for (i, c) in components.iter().enumerate() {
52:         if i > 0 {
53:             out_str.push('/');
54:         }
55:         out_str.push_str(c.as_os_str().to_str().unwrap());
56:     }
57: 
58:     Ok(PathBuf::from(out_str))
59: }
60: 
